package com.nigson.acceptance.pricing;

import java.time.Clock;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import static org.assertj.core.api.Assertions.*;
import com.nigson.commerce.authorization.*;
import com.nigson.commerce.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.security.PrivateWorkload;

class DistributorEntitlementPersistenceTest {
 private PricingFixture f;private DistributorEntitlementService service;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"pricing-check supplies isolated PostgreSQL");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_TEST_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");f=new PricingFixture(new JdbcTemplate(ds),new DataSourceTransactionManager(ds));var commands=new PlatformStore(f.jdbc,f.manager,Clock.systemUTC(),f.metrics);service=new DistributorEntitlementService(f.jdbc,commands,new AuditWriter(f.jdbc,Clock.systemUTC(),f.metrics),f.metrics,Clock.systemUTC(),3,"SYNTHETIC_DISTRIBUTOR_BUY");}
 @AfterEach void cleanup(){if(f!=null){for(UUID org:f.jdbc.query("SELECT id FROM commerce.organization WHERE created_by='nigson-experience'",(r,n)->r.getObject(1,UUID.class)))f.jdbc.update("DELETE FROM commerce.outbox_event WHERE aggregate_id=?",org);f.close();}}
 private PrivateWorkload.Proof proof(){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-117")).findFirst().orElseThrow();return new PrivateWorkload.Proof(route.client(),"synthetic-experience-workload",route,null);}
 private EntitlementValues.Command command(UUID command,UUID app,UUID party,EntitlementValues.Decision decision){return new EntitlementValues.Command(command,app,party,"Synthetic distributor","NG","SYNTH-"+app,decision,f.market,null);}
 @Test void activationAcknowledgesOnlyCommittedOwnedStateAndDuplicateIsExactlyOnce(){UUID command=UUID.randomUUID(),app=UUID.randomUUID();var input=command(command,app,f.customer.party(),EntitlementValues.Decision.ACTIVATE);var ack=service.execute(proof(),input,0,"idempotency-"+command,UUID.randomUUID());f.organizations.add(ack.organizationId());assertThat(ack.commandId()).isEqualTo(command);assertThat(ack.state()).isEqualTo("ACTIVE");assertThat(ack.revision()).isZero();assertThat(f.jdbc.queryForObject("SELECT status FROM commerce.organization WHERE id=?",String.class,ack.organizationId())).isEqualTo("ACTIVE");assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.organization_membership WHERE organization_id=? AND party_id=? AND role='OWNER' AND status='ACTIVE'",Integer.class,ack.organizationId(),f.customer.party())).isEqualTo(1);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.account_entitlement WHERE organization_id=? AND entitlement='SYNTHETIC_DISTRIBUTOR_BUY' AND status='ACTIVE' AND source_application_id=? AND approval_command_id=?",Integer.class,ack.organizationId(),app,command)).isEqualTo(1);var replay=service.execute(proof(),input,0,"idempotency-"+command,UUID.randomUUID());assertThat(replay).isEqualTo(ack);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.outbox_event WHERE aggregate_id=? AND event_type='distributor.entitlement.changed.v1'",Integer.class,ack.organizationId())).isEqualTo(1);var event=EventCodec.decode(f.jdbc.queryForObject("SELECT payload::text FROM commerce.outbox_event WHERE aggregate_id=?",String.class,ack.organizationId()));assertThat(event.path("payload").path("state").asString()).isEqualTo("ACTIVE");UUID entitlementId=f.jdbc.queryForObject("SELECT id FROM commerce.account_entitlement WHERE organization_id=?",UUID.class,ack.organizationId());assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='ENTITLEMENT_APPROVAL'",Integer.class,entitlementId)).isEqualTo(1);assertThat(f.metrics.get("nigson.authorization.entitlement").tag("operation","ACTIVATE").counter().count()).isEqualTo(1);}
 @Test void suspensionCommitsBeforeAckAndRevokesBuyingWithoutDestroyingMembership(){UUID command=UUID.randomUUID(),app=UUID.randomUUID();var active=service.execute(proof(),command(command,app,f.customer.party(),EntitlementValues.Decision.ACTIVATE),0,"activate-"+command,UUID.randomUUID());f.organizations.add(active.organizationId());var suspendedCommand=UUID.randomUUID();var input=command(suspendedCommand,app,f.customer.party(),EntitlementValues.Decision.SUSPEND);var ack=service.execute(proof(),input,0,"suspend-"+suspendedCommand,UUID.randomUUID());assertThat(ack.state()).isEqualTo("SUSPENDED");assertThat(ack.revision()).isEqualTo(1);assertThat(f.jdbc.queryForObject("SELECT status FROM commerce.account_entitlement WHERE organization_id=?",String.class,active.organizationId())).isEqualTo("SUSPENDED");assertThat(f.jdbc.queryForObject("SELECT status FROM commerce.organization_membership WHERE organization_id=? AND party_id=?",String.class,active.organizationId(),f.customer.party())).isEqualTo("ACTIVE");assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.outbox_event WHERE aggregate_id=? AND event_type='distributor.entitlement.changed.v1'",Integer.class,active.organizationId())).isEqualTo(2);assertThatThrownBy(()->f.prices.price(f.customer,f.sku,"NG","2",active.organizationId())).hasMessage("ACCESS_DENIED");assertThat(service.execute(proof(),input,0,"suspend-"+suspendedCommand,UUID.randomUUID())).isEqualTo(ack);}
 @Test void rejectsWrongOwnerScopeAndConflictingReplayBeforeMutation(){UUID command=UUID.randomUUID(),app=UUID.randomUUID();var input=command(command,app,f.customer.party(),EntitlementValues.Decision.ACTIVATE);var wrong=new PrivateWorkload.Proof("nigson-integration","synthetic",PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-118")).findFirst().orElseThrow(),null);assertThatThrownBy(()->service.execute(wrong,input,0,"wrong-owner",UUID.randomUUID())).hasMessage("ACCESS_DENIED");var first=service.execute(proof(),input,0,"same",UUID.randomUUID());f.organizations.add(first.organizationId());var changed=new EntitlementValues.Command(command,app,f.customer.party(),"Changed synthetic distributor","NG","SYNTH-"+app,EntitlementValues.Decision.ACTIVATE,f.market,null);assertThatThrownBy(()->service.execute(proof(),changed,0,"same",UUID.randomUUID())).hasMessage("IDEMPOTENCY_HASH_MISMATCH");assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.organization WHERE id=?",Integer.class,first.organizationId())).isEqualTo(1);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.outbox_event WHERE aggregate_id=?",Integer.class,first.organizationId())).isEqualTo(1);}
}
